         return PidIdentity::Gone;
     }
     let Some(live) = process_start_iso(pid) else {
         return PidIdentity::Gone;
     };
     if start_time.is_empty() || live.is_empty() {
         return PidIdentity::Unknown;
     }
     if same_start_time(&live, start_time) {
         PidIdentity::Alive
     } else {
         PidIdentity::Gone
     }
