 /// Terminate one process by its pid (best effort). Callers check its identity first
 /// ([`pid_identity`]): a pid is never killed on a guess.
 pub fn terminate_pid(pid: u32) {
     if pid == 0 || pid == std::process::id() {
         return;
     }
     imp::terminate_pid(pid)
