+$raw = [string]$env:FAKE_CODEX_ARGS
+if ($raw -match '--version') { Write-Output 'codex-cli 0.155.1-fake'; exit 0 }
+if ($raw -match '^\s*login\s+status(\s|$)') { [Console]::Error.WriteLine('Logged in using ChatGPT'); exit 0 }
