+        .env("C3_TELEMETRY_HUB", "http://127.0.0.1:9/T")
+        .env("C3_PRIORS", "off")
+        .env("CODEX_CONSULT_TEST_MODE", "1")
+        .env("CODEX_CONSULT_TEST_KILL_PAUSE_MS", "120000");
