720: /// "started at or after" stamp for the message; `since` is the same instant for the comparison.
721: /// With a bridge pid on Windows, a process counts when its parent is that pid and it started at or
722: /// after `since` (and, if the pid was reused by a live process, before that reuse). Otherwise the
723: /// machine-wide "looks like codex" rule applies (labelled "task not verifiable"); (wave 29, E27) the
724: /// Codex desktop app's servers and helpers ([`codex_server_exclusion`]) are left out and named in
725: /// `check` ("excluded: pid N codex.exe [codex app-server]", at most 6, then "(+k more)") and in
726: /// `excluded`. This process and its ancestors are never counted. (wave 3c, F23-2) A row whose start
727: /// time could not be read (`created: None`) is never skipped: it counts as started at or after
728: /// `since` (and before a reuse of the bridge's pid), its rule says so ([`START_UNREADABLE_COUNTED`]).
729: /// The plugin's `Win32_Process.CreationDate` is always read; C3's table (`GetProcessTimes`) cannot
730: /// read a protected or another user's process, which must never release a record by being skipped.
731: #[allow(clippy::too_many_arguments)]
732: pub fn find_codex_processes(
733:     procs: &[ScanProc],
734:     since: chrono::DateTime<chrono::Utc>,
735:     since_text: &str,
736:     launcher: &str,
737:     bridge_pid: u32,
738:     self_pid: u32,
739:     on_windows: bool,
740: ) -> ScanOutcome {
741:     let by_parent = on_windows && bridge_pid > 0;
742:     let rules = if by_parent {
743:         format!("children of the interrupted bridge pid {bridge_pid}")
744:     } else {
745:         "name codex*, or a command line containing the recorded launcher or @openai/codex; not the Codex app's servers and helpers"
746:             .to_string()
747:     };
748:     let scanner = if on_windows {
749:         "Win32_Process scan"
750:     } else {
751:         "ps scan"
752:     };
753:     let mut check = format!("{scanner} ({rules}; started at or after {since_text})");
754: 
755:     use std::collections::{HashMap, HashSet};
756:     let by_id: HashMap<u32, &ScanProc> = procs.iter().map(|p| (p.pid, p)).collect();
757:     // Never count ourselves or our ancestors (a shell that started this run may carry the launcher
758:     // path on its command line).
759:     let mut excluded: HashSet<u32> = HashSet::new();
760:     let mut cur = self_pid;
761:     let mut guard = 0;
762:     while guard < 64 && cur > 0 && !excluded.contains(&cur) {
763:         excluded.insert(cur);
764:         match by_id.get(&cur) {
765:             Some(p) => cur = p.ppid,
766:             None => break,
767:         }
768:         guard += 1;
769:     }
770: 
771:     let mut found = Vec::new();
772:     let mut app_servers: Vec<ExcludedProc> = Vec::new();
773:     if by_parent {
774:         // A live process holding the bridge's pid now is a reuse; only children created before it
775:         // started are ours.
776:         let reused_at = by_id.get(&bridge_pid).and_then(|p| p.created);
777:         for p in procs {
778:             if excluded.contains(&p.pid) || p.ppid != bridge_pid {
779:                 continue;
780:             }
781:             let rule = match p.created {
782:                 // (wave 3c, F23-2) a child whose start time cannot be read is never filtered out:
783:                 // it may have started at or after `since` and before any reuse (fail-closed)
784:                 None => format!(
785:                     "child of the interrupted bridge (ppid {bridge_pid}); {START_UNREADABLE_COUNTED}"
786:                 ),
787:                 Some(c) if c < since => continue,
788:                 Some(c) => {
789:                     if let Some(r) = reused_at {
790:                         if c >= r {
791:                             continue;
792:                         }
793:                     }
794:                     format!("child of the interrupted bridge (ppid {bridge_pid})")
795:                 }
796:             };
797:             found.push(FoundProc {
798:                 pid: p.pid,
799:                 name: p.name.clone(),
800:                 rule,
801:             });
802:         }
803:     } else {
804:         for p in procs {
805:             if excluded.contains(&p.pid) {
806:                 continue;
807:             }
808:             // (wave 3c, F23-2) a start time that cannot be read counts as "at or after `since`":
809:             // such a process is judged by the rule like any recent one (fail-closed)
810:             let start_unknown = match p.created {
811:                 None => true,
812:                 Some(c) if c < since => continue,
813:                 Some(_) => false,
814:             };
815:             let m = codex_match(&p.name, &p.command_line, launcher);
816:             if !m.rule.is_empty() {
817:                 let unknown = if start_unknown {
818:                     format!("; {START_UNREADABLE_COUNTED}")
819:                 } else {
820:                     String::new()
821:                 };
822:                 found.push(FoundProc {
823:                     pid: p.pid,
824:                     name: p.name.clone(),
825:                     rule: format!("{}, task not verifiable{unknown}", m.rule),
826:                 });
827:             } else if !m.excluded.is_empty() {
828:                 app_servers.push(ExcludedProc {
829:                     pid: p.pid,
830:                     name: p.name.clone(),
830:                     name: p.name.clone(),
831:                     why: m.excluded,
832:                 });
833:             }
834:         }
835:         // (wave 29, E27) what was left out, said where the scan is reported (at most 6 named)
836:         if !app_servers.is_empty() {
837:             let shown = app_servers
838:                 .iter()
839:                 .take(6)
840:                 .map(|e| format!("pid {} {} [{}]", e.pid, e.name, e.why))
841:                 .collect::<Vec<_>>()
842:                 .join(", ");
843:             let more = if app_servers.len() > 6 {
844:                 format!(" (+{} more)", app_servers.len() - 6)
845:             } else {
846:                 String::new()
847:             };
848:             check.pop();
849:             check.push_str(&format!("; excluded: {shown}{more})"));
850:         }
851:     }
852:     ScanOutcome {
853:         found,
854:         check,
855:         failed: false,
856:         excluded: app_servers,
857:     }
858: }
