890: /// [`descendants_of`] over a given process table (pure): every row is visited at most once, so
891: /// the walk is bounded by the table itself and never truncates (F09-4).
892: pub fn descendants_in(procs: &[ScanProc], pid: u32) -> Vec<u32> {
893:     let mut seen: std::collections::HashSet<u32> = std::collections::HashSet::new();
894:     seen.insert(pid);
895:     let mut out = Vec::new();
896:     let mut frontier = vec![pid];
897:     while let Some(parent) = frontier.pop() {
898:         for p in procs.iter().filter(|p| p.ppid == parent) {
899:             if seen.insert(p.pid) {
900:                 out.push(p.pid);
901:                 frontier.push(p.pid);
902:             }
903:         }
904:     }
905:     out
906: }
